import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline
import os

# Set hipcc as CXX compiler
os.environ["CXX"] = "hipcc"

cpp_source = """
#include <hip/hip_runtime.h>
#include <torch/extension.h>

#define BM 128
#define BN 128
#define BK 32
#define TM 8
#define TN 8

__global__ void skinny_matmul_kernel(const float* __restrict__ A, const float* __restrict__ B, float* __restrict__ C, int M, int N, int K) {
    int bx = blockIdx.x;
    int by = blockIdx.y;

    int tx = threadIdx.x; 
    int ty = threadIdx.y; 
    int tid = ty * 16 + tx;

    int row_start = by * BM;
    int col_start = bx * BN;

    __shared__ float As[BM][BK];
    __shared__ float Bs[BK][BN];

    const float4* A_ptr = reinterpret_cast<const float4*>(A);

    // Load A (M, K) tile. K=32. Tile is (BM, 32).
    // Access A[row_start + r, c]. c in 0..31.
    // 128 rows, 32 cols -> 4096 floats.
    // 256 threads. 16 floats per thread (4 float4).

    #pragma unroll
    for (int i = 0; i < 4; ++i) {
        int load_idx = tid + i * 256;
        int row = load_idx / 8;        // 0..127
        int col_vec = load_idx % 8;    // 0..7 (each is float4, so 0..31 floats)

        if (row < BM) { 
             int global_row = row_start + row;
             if (global_row < M) {
                 float4 val = A_ptr[global_row * 8 + col_vec];
                 As[row][col_vec*4 + 0] = val.x;
                 As[row][col_vec*4 + 1] = val.y;
                 As[row][col_vec*4 + 2] = val.z;
                 As[row][col_vec*4 + 3] = val.w;
             } else {
                 As[row][col_vec*4 + 0] = 0.0f;
                 As[row][col_vec*4 + 1] = 0.0f;
                 As[row][col_vec*4 + 2] = 0.0f;
                 As[row][col_vec*4 + 3] = 0.0f;
             }
        }
    }

    // Load B (K, N) tile. K=32. Tile is (32, BN).
    // Access B[r, col_start + c]. r in 0..31.
    // 32 rows, 128 cols -> 4096 floats.
    // 256 threads. 16 floats per thread.

    #pragma unroll
    for (int i = 0; i < 4; ++i) {
        int load_idx = tid + i * 256;
        int row = load_idx / 32;       // 0..31
        int col_vec = load_idx % 32;   // 0..31 (each is float4, so 0..127 floats)

        if (row < BK) {
             int global_col = col_start + col_vec * 4;
             if (global_col < N) {
                 const float4* B_row_ptr = reinterpret_cast<const float4*>(B + row * N + global_col);
                 float4 val = B_row_ptr[0];
                 Bs[row][col_vec*4 + 0] = val.x;
                 Bs[row][col_vec*4 + 1] = val.y;
                 Bs[row][col_vec*4 + 2] = val.z;
                 Bs[row][col_vec*4 + 3] = val.w;
             } else {
                 Bs[row][col_vec*4 + 0] = 0.0f;
                 Bs[row][col_vec*4 + 1] = 0.0f;
                 Bs[row][col_vec*4 + 2] = 0.0f;
                 Bs[row][col_vec*4 + 3] = 0.0f;
             }
        }
    }

    __syncthreads();

    float acc[TM][TN] = {0.0f};

    #pragma unroll
    for (int k = 0; k < BK; ++k) {
        float a_cache[TM];
        float b_cache[TN];

        #pragma unroll
        for(int i=0; i<TM; ++i) a_cache[i] = As[ty*TM + i][k];

        #pragma unroll
        for(int j=0; j<TN; ++j) b_cache[j] = Bs[k][tx*TN + j];

        #pragma unroll
        for(int i=0; i<TM; ++i) {
            #pragma unroll
            for(int j=0; j<TN; ++j) {
                acc[i][j] += a_cache[i] * b_cache[j];
            }
        }
    }

    int global_row_base = row_start + ty * TM;
    int global_col_base = col_start + tx * TN;

    #pragma unroll
    for(int i=0; i<TM; ++i) {
        int r = global_row_base + i;
        if (r < M) {
             if (global_col_base + TN <= N) {
                 float4* C_ptr = reinterpret_cast<float4*>(C + r * N + global_col_base);
                 float4 v1, v2;
                 v1.x = acc[i][0]; v1.y = acc[i][1]; v1.z = acc[i][2]; v1.w = acc[i][3];
                 v2.x = acc[i][4]; v2.y = acc[i][5]; v2.z = acc[i][6]; v2.w = acc[i][7];
                 C_ptr[0] = v1;
                 C_ptr[1] = v2;
             } else {
                 for (int j=0; j<TN; ++j) {
                     if (global_col_base + j < N) {
                         C[r * N + global_col_base + j] = acc[i][j];
                     }
                 }
             }
        }
    }
}

torch::Tensor matmul_hip(torch::Tensor A, torch::Tensor B) {
    int M = A.size(0);
    int K = A.size(1);
    int N = B.size(1);

    auto C = torch::empty({M, N}, A.options());

    dim3 block(16, 16);
    dim3 grid((N + 127) / 128, (M + 127) / 128);

    skinny_matmul_kernel<<<grid, block>>>(A.data_ptr<float>(), B.data_ptr<float>(), C.data_ptr<float>(), M, N, K);

    return C;
}
