    int ty = threadIdx.y; 
    int tid = ty * 8 + tx;

    int row_start = by * BM;
    int col_start = bx * BN;

    // Pad inner dimensions
    __shared__ float As[BM][BK + PAD];
    __shared__ float Bs[BK][BN + PAD];

    const float4* A_ptr = reinterpret_cast<const float4*>(A);
    const float4* B_ptr = reinterpret_cast<const float4*>(B);

    // Load A into Shared
    int load_idx_a = tid;
    #pragma unroll
