__global__ void skinny_matmul_kernel(const float* __restrict__ A, const float* __restrict__ B, float* __restrict__ C, int M, int N, int K) {
    int bx = blockIdx.x;
    int by = blockIdx.y;

    int tx = threadIdx.x; 
    int ty = threadIdx.y; 
    int tid = ty * 16 + tx;

    int row_start = by * BM;
    int col_start = bx * BN;

    __shared__ float As[BM][BK];
    __shared__ float Bs[BK][BN];

    const float4* A_ptr = reinterpret_cast<const float4*>(A);

    // Load A (M, K) tile. K=32. Tile is (BM, 32).
    // Access A[row_start + r, c]. c in 0..31.
    // 128 rows, 32 cols -> 4096 floats.
    // 256 threads. 16 floats per thread (4 float4).

    #pragma unroll
    for (int i = 0; i < 4; ++i) {
        int load_idx = tid + i * 256;
        int row = load_idx / 8;        // 0..127
        int col_vec = load_idx % 8;    // 0..7 (each is float4, so 0..31 floats)

