                 Bs[row][col_vec*4 + 2] = 0.0f;
                 Bs[row][col_vec*4 + 3] = 0.0f;
             }
        }
    }

    __syncthreads();

    float acc[TM][TN] = {0.0f};

    #pragma unroll
    for (int k = 0; k < BK; ++k) {
        float a_cache[TM];
        float b_cache[TN];

        #pragma unroll
        for(int i=0; i<TM; ++i) a_cache[i] = As[ty*TM + i][k];

        #pragma unroll
        for(int j=0; j<TN; ++j) b_cache[j] = Bs[k][tx*TN + j];

        #pragma unroll
